contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value) public payable {
        require(to != address(0));
        // Observe balances before
        uint256 beforeFrom = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);

        // Attempt transfer and record whether it reverted
        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balances after
        uint256 afterFrom = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);

        // If the call did not revert, the combined balance of the two addresses must be conserved
        // If it reverted, we make no requirement about balances changing.
        assert(reverted || (afterFrom + afterTo == beforeFrom + beforeTo));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // target: whose freeze status to set; flag: desired frozen status
    function run(address target, bool flag) public payable {
        require(target != address(0)); // ensure observable getter works and avoid trivial zero-address edge

        // Record owner and previous frozen status
        address ownerBefore = c.owner();
        bool frozenBefore = c.frozenAccount(target);

        // Attempt to call freezeAccount and capture whether it reverted
        bool reverted;
        try c.freezeAccount(target, flag) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe frozen status after call
        bool frozenAfter = c.frozenAccount(target);

        // If call succeeded (did not revert) then: frozenAfter equals flag AND this contract was ownerBefore
        // If call reverted then nothing is required about frozenAfter, but we assert the disjunction
        assert((!reverted && frozenAfter == flag && ownerBefore == address(this)) || (reverted && (ownerBefore != address(this) || frozenAfter == frozenBefore)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount to burn and an address to observe balances (we will use address(this) as caller)
    function run(uint256 burnAmount, address addr) public payable {
        require(true);
        // read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalanceCaller = c.balanceOf(address(this));
        uint256 beforeBalanceAddr = c.balanceOf(addr);

        // attempt burn and record whether it reverted
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalanceCaller = c.balanceOf(address(this));
        uint256 afterBalanceAddr = c.balanceOf(addr);

        // If burn succeeded then caller must have been owner and balances/totalSupply reduced by burnAmount from caller
        // We cannot directly read owner if not allowed, but owner() is public so we can compare.
        address owner = c.owner();
        // assert: if not reverted then caller is owner and totalSupply decreased by burnAmount and caller balance decreased by burnAmount, other balances unchanged
        assert(reverted || (
            owner == address(this)
            && afterTotal + burnAmount == beforeTotal
            && afterBalanceCaller + burnAmount == beforeBalanceCaller
            && afterBalanceAddr == beforeBalanceAddr
        ));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));
        // Read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(target);

        // Try calling mintToken and record whether it reverted
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(target);

        // The general rule:
        // If mintToken did not revert then afterTotal == beforeTotal + mintedAmount
        // and afterBal == beforeBal + mintedAmount. If it reverted then both values unchanged.
        assert((!reverted && afterTotal == beforeTotal + mintedAmount && afterBal == beforeBal + mintedAmount) ||
               (reverted && afterTotal == beforeTotal && afterBal == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // test: call transfer from this contract to a provided recipient with provided value
    // property: if call does not revert then the recipient is not address(0)
    function run(address to, uint256 value) public payable {
        require(to != address(0) || to == address(0)); // no-op to allow any address
        // ensure this contract has enough balance to attempt a transfer when possible
        // We can mint tokens to this contract by calling mintToken as owner only — but we are not owner
        // So we cannot guarantee balance; we just attempt the transfer and record revert
        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // If the call did not revert, then the recipient cannot be the zero address per contract's _transfer require(_to != address(0))
        assert(reverted || to != address(0));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 v) public payable {
        require(to != address(0));
        // Read balances before
        uint256 before_sender = c.balanceOf(address(this));
        uint256 before_recipient = c.balanceOf(to);

        // Ensure this contract is not frozen: only owner can change frozenAccount, but we can't assume owner
        // We attempt the transfer and record whether it reverted
        bool reverted;
        try c.transfer(to, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after_sender = c.balanceOf(address(this));
        uint256 after_recipient = c.balanceOf(to);

        // If transfer succeeded (didn't revert) then sender lost v and recipient gained v
        // Use inequalities that avoid underflow in the assert expression itself
        assert(reverted || (after_sender + v == before_sender && after_recipient == before_recipient + v));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // ensure this contract is the owner by relying on constructor-deployed c: the checker deploys c with owner = deployer (InvMutTest), per problem statement
        // read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));
        bool reverted;
        // attempt burn as this contract
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(address(this));
        // If call reverted then both totalSupply and balance must be unchanged; otherwise both decreased by exactly burnAmount
        assert(reverted ? (afterTotal == beforeTotal && afterBal == beforeBal) : (afterTotal + burnAmount == beforeTotal && afterBal + burnAmount == beforeBal));
    }
}
